"""Reports: requested through the API, generated by a background job, downloaded when ready."""

import re
import uuid
from collections.abc import Callable
from datetime import UTC, datetime
from typing import Any

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import undefer

from app.core.exceptions import AppError, Forbidden, NotFound
from app.domain.enums import JobType
from app.domain.principal import Principal
from app.modules.jobs.service import JobService
from app.modules.reports.builders import BUILDERS, TITLES
from app.modules.reports.models import Report
from app.modules.reports.render import to_pdf, to_xlsx
from app.workers.runner import JobContext

CONTENT_TYPES = {
    "pdf": "application/pdf",
    "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
}


def filename_for(title: str, fmt: str) -> str:
    slug = re.sub(r"[^A-Za-z0-9]+", "-", title).strip("-")[:80] or "report"
    return f"{slug}-{datetime.now(UTC):%Y%m%d}.{fmt}"


class ReportService:
    def __init__(self, session: AsyncSession, principal: Principal, notify: Callable[[], None]) -> None:
        if principal.tenant_id is None:
            raise Forbidden("Reports belong to an organization; open the app as one to use them")
        self.s = session
        self.principal = principal
        self.tenant_id: uuid.UUID = principal.tenant_id
        self.notify = notify

    async def request(self, report_type: str, fmt: str, parameters: dict[str, Any]) -> Report:
        report = Report(
            tenant_id=self.tenant_id,
            user_id=self.principal.user_id,
            report_type=report_type,
            format=fmt,
            title=TITLES[report_type],
            parameters=parameters,
        )
        self.s.add(report)
        await self.s.flush()
        job = await JobService(self.s, self.principal, self.notify).create(
            JobType.REPORT, {"report_id": str(report.id)}, None
        )
        report.job_id = job.id
        await self.s.commit()
        await self.s.refresh(report)
        return report

    async def list_reports(self, limit: int) -> list[Report]:
        return list(await self.s.scalars(select(Report).order_by(Report.created_at.desc()).limit(limit)))

    async def get(self, report_id: uuid.UUID, *, with_data: bool = False) -> Report:
        stmt = select(Report).where(Report.id == report_id)
        if with_data:
            stmt = stmt.options(undefer(Report.data))
        report = await self.s.scalar(stmt)
        if report is None:
            raise NotFound("Report not found")
        return report


async def report_handler(ctx: JobContext) -> dict[str, Any]:
    report_id = uuid.UUID(ctx.input["report_id"])
    async with ctx.session() as s:
        report = await s.get(Report, report_id)
        if report is None:
            raise NotFound("Report not found")
        await ctx.progress("building", 20)
        try:
            data = await BUILDERS[report.report_type](s, report.tenant_id, report.parameters)
        except AppError as exc:  # bad parameters: a clear message on the report, not a crashed job
            report.status, report.error = "failed", exc.detail or exc.title
            await s.commit()
            return {"report_id": str(report.id), "status": "failed", "error": report.error}
        await ctx.progress("rendering", 70)
        content = to_pdf(data) if report.format == "pdf" else to_xlsx(data)
        report.title = data.title[:200]
        report.filename = filename_for(data.title, report.format)
        report.content_type = CONTENT_TYPES[report.format]
        report.size_bytes = len(content)
        report.data = content
        report.status = "ready"
        await s.commit()
        return {"report_id": str(report.id), "status": "ready", "size_bytes": len(content)}
